// Invoke only from the one existing, authenticated Telegram ingress router.
const cfg={configured:false,adapter_url:'https://openclaw-communication.home.arpa:19443',destination:'replace-selected-authorized-destination',chat_id:'replace-selected-private-chat-id',user_id:'replace-selected-operator-id'};
if (!cfg.configured || !/^[0-9]+$/.test(cfg.chat_id) || !/^[0-9]+$/.test(cfg.user_id)) throw new Error('Selected private chat and sender approval required');
const update=$json; const msg=update.message;
if (!Number.isSafeInteger(update.update_id) || !msg || msg.chat?.type!=='private' || String(msg.chat.id)!==cfg.chat_id || String(msg.from?.id)!==cfg.user_id || msg.from?.is_bot || typeof msg.text!=='string' || msg.text.length>4000 || !msg.text.startsWith('/openclaw ')) return [];
return [{json:{adapter_url:cfg.adapter_url,conversation:'operator',destination:cfg.destination,request_id:'telegram:'+update.update_id,text:msg.text.slice(10)}}];
